-- GENERATED by porting frontend-horarios/supabase/*.sql (01-33, without 00 and 05)
-- through pg_dump, then: auth.uid() -> horarios.fn_usuario_actual(), public -> horarios,
-- RLS policies / auth users functions / auth.users FK removed. Executed with
-- check_function_bodies = off, in pg_dump dependency order.

-- TABLE: ambientes
CREATE TABLE horarios.ambientes (
    id bigint NOT NULL,
    codigo text NOT NULL,
    nombre text,
    tipo text DEFAULT 'laboratorio'::text NOT NULL,
    capacidad integer DEFAULT 0 NOT NULL,
    tipo_equipo text,
    ubicacion text,
    estado text DEFAULT 'activo'::text NOT NULL,
    color text DEFAULT '#2563eb'::text NOT NULL,
    orden integer DEFAULT 0 NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ambientes_capacidad_check CHECK ((capacidad >= 0)),
    CONSTRAINT ambientes_estado_check CHECK ((estado = ANY (ARRAY['activo'::text, 'mantenimiento'::text, 'baja'::text]))),
    CONSTRAINT ambientes_tipo_check CHECK ((tipo = ANY (ARRAY['laboratorio'::text, 'aula'::text, 'auditorio'::text, 'otro'::text])))
);

-- FUNCTION: fn_ambientes_libres(date, time without time zone, time without time zone, text, jsonb)
CREATE FUNCTION horarios.fn_ambientes_libres(p_fecha date, p_hora_inicio time without time zone, p_hora_fin time without time zone, p_tipo text DEFAULT NULL::text, p_ignorar jsonb DEFAULT '{}'::jsonb) RETURNS SETOF horarios.ambientes
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select am.*
  from horarios.ambientes am
  where am.estado = 'activo'
    and (p_tipo is null or am.tipo = p_tipo)
    and not exists (
      select 1
      from horarios.fn_ocupaciones(p_fecha, p_fecha,
                                 nullif(p_ignorar->>'reserva_id', '')::bigint,
                                 nullif(p_ignorar->>'cesion_id', '')::bigint) o
      where o.ambiente_id = am.id
        and o.hora_inicio < p_hora_fin
        and p_hora_inicio < o.hora_fin
        and not coalesce(o.asignacion_horario_id = nullif(p_ignorar->>'asignacion_horario_id', '')::bigint, false)
    )
  order by case am.tipo when 'laboratorio' then 0 when 'aula' then 1 else 2 end, am.orden, am.codigo;
$$;

-- FUNCTION: fn_ambientes_libres_fechas(date[], time without time zone, time without time zone, text, jsonb)
CREATE FUNCTION horarios.fn_ambientes_libres_fechas(p_fechas date[], p_hora_inicio time without time zone, p_hora_fin time without time zone, p_tipo text DEFAULT NULL::text, p_ignorar jsonb DEFAULT '{}'::jsonb) RETURNS SETOF horarios.ambientes
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  with o as materialized (
    select oc.*
    from horarios.fn_ocupaciones((select min(f) from unnest(p_fechas) f), (select max(f) from unnest(p_fechas) f),
                               nullif(p_ignorar->>'reserva_id', '')::bigint,
                               nullif(p_ignorar->>'cesion_id', '')::bigint) oc
    where oc.fecha = any(p_fechas)
      and oc.hora_inicio < p_hora_fin
      and p_hora_inicio < oc.hora_fin
      and not coalesce(oc.asignacion_id = nullif(p_ignorar->>'asignacion_id', '')::bigint, false)
      and not coalesce(oc.asignacion_horario_id = nullif(p_ignorar->>'asignacion_horario_id', '')::bigint, false)
  )
  select am.*
  from horarios.ambientes am
  where am.estado = 'activo'
    and (p_tipo is null or am.tipo = p_tipo)
    and coalesce(array_length(p_fechas, 1), 0) > 0
    and not exists (select 1 from o where o.ambiente_id = am.id)
  order by case am.tipo when 'laboratorio' then 0 when 'aula' then 1 else 2 end, am.orden, am.codigo;
$$;

-- FUNCTION: fn_asignar_turno(uuid, text, boolean)
CREATE FUNCTION horarios.fn_asignar_turno(p_usuario uuid, p_turno text, p_sabado boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'horarios'
    AS $$
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado pueden asignar turnos.';
  end if;
  if p_turno is not null and p_turno not in ('M','MD','T','N') then
    raise exception 'Turno inválido.';
  end if;
  update horarios.perfiles
     set turno_habitual = p_turno, sabado_rotativo = coalesce(p_sabado, false)
   where id = p_usuario;
end $$;

-- FUNCTION: fn_conflictos(date, date)
CREATE FUNCTION horarios.fn_conflictos(p_desde date, p_hasta date) RETURNS TABLE(tipo_choque text, fecha date, hora_inicio time without time zone, hora_fin time without time zone, ambiente_id bigint, docente_id bigint, clave_a text, origen_a text, titulo_a text, detalle_a text, ambiente_a bigint, asignacion_a bigint, horario_a bigint, cesion_a bigint, reserva_a bigint, reserva_horario_a bigint, clave_b text, origen_b text, titulo_b text, detalle_b text, ambiente_b bigint, asignacion_b bigint, horario_b bigint, cesion_b bigint, reserva_b bigint, reserva_horario_b bigint, mensaje text)
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  with o as materialized (
    select * from horarios.fn_ocupaciones(p_desde, p_hasta)
  ),
  pares as (
    select a.*,
           b.clave as b_clave, b.origen as b_origen, b.titulo as b_titulo, b.detalle as b_detalle,
           b.ambiente_id as b_ambiente, b.docente_id as b_docente, b.asignacion_id as b_asig,
           b.asignacion_horario_id as b_hor, b.cesion_id as b_ces, b.reserva_id as b_res,
           b.reserva_horario_id as b_rh,
           greatest(a.hora_inicio, b.hora_inicio) as solape_ini,
           least(a.hora_fin, b.hora_fin)          as solape_fin,
           case when a.ambiente_id = b.ambiente_id then 'ambiente' else 'docente' end as tipo
    from o a
    join o b on a.fecha = b.fecha
            and a.clave < b.clave
            and a.hora_inicio < b.hora_fin
            and b.hora_inicio < a.hora_fin
    where (a.ambiente_id = b.ambiente_id
           and (a.docente_id is null or b.docente_id is null or a.docente_id <> b.docente_id))
       or (a.docente_id = b.docente_id and a.ambiente_id <> b.ambiente_id)
  )
  select p.tipo, p.fecha, p.solape_ini, p.solape_fin,
         case when p.tipo = 'ambiente' then p.ambiente_id end,
         case when p.tipo = 'docente'  then p.docente_id  end,
         p.clave, p.origen, p.titulo, p.detalle, p.ambiente_id,
         p.asignacion_id, p.asignacion_horario_id, p.cesion_id, p.reserva_id, p.reserva_horario_id,
         p.b_clave, p.b_origen, p.b_titulo, p.b_detalle, p.b_ambiente,
         p.b_asig, p.b_hor, p.b_ces, p.b_res, p.b_rh,
         case when p.tipo = 'ambiente' then
           format('Choque de ambiente: %s el %s de %s a %s está ocupado por "%s" (%s) y por "%s" (%s).',
                  am.codigo, horarios.fn_texto_fecha(p.fecha),
                  horarios.fn_texto_hora(p.solape_ini), horarios.fn_texto_hora(p.solape_fin),
                  p.titulo, p.detalle, p.b_titulo, p.b_detalle)
         else
           format('Choque de docente: %s estaría en %s ("%s") y en %s ("%s") al mismo tiempo el %s de %s a %s.',
                  horarios.fn_nombre_docente(p.docente_id),
                  am.codigo, p.titulo, bm.codigo, p.b_titulo,
                  horarios.fn_texto_fecha(p.fecha),
                  horarios.fn_texto_hora(p.solape_ini), horarios.fn_texto_hora(p.solape_fin))
         end
  from pares p
  join horarios.ambientes am on am.id = p.ambiente_id
  join horarios.ambientes bm on bm.id = p.b_ambiente
  order by p.fecha, p.solape_ini;
$$;

-- FUNCTION: fn_dashboard_detalle(date, date)
CREATE FUNCTION horarios.fn_dashboard_detalle(p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'horarios'
    AS $$
declare
  v_zona constant text := 'America/La_Paz';
  r jsonb;
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado pueden ver el dashboard.';
  end if;
  if p_desde is null or p_hasta is null or p_hasta < p_desde or (p_hasta - p_desde) > 400 then
    raise exception 'Rango de fechas inválido.';
  end if;

  with o as (   -- ocupación de laboratorios con sus horas
    select x.*, extract(epoch from (x.hora_fin - x.hora_inicio)) / 3600.0 as horas
      from horarios.fn_ocupaciones(p_desde, p_hasta) x
      join horarios.ambientes am on am.id = x.ambiente_id and am.tipo = 'laboratorio'
  ),
  t as (        -- tickets del período con su hora local y el turno en que se crearon
    select a.*, (a.creado_en at time zone v_zona) as local,
           coalesce((select h.turno from horarios.horarios_turno h
                      where h.hora_inicio <= (a.creado_en at time zone v_zona)::time
                      order by ((a.creado_en at time zone v_zona)::time < h.hora_fin) desc, h.hora_inicio desc
                      limit 1), 'N') as turno_creado
      from horarios.atenciones a
     where (a.creado_en at time zone v_zona)::date between p_desde and p_hasta
  ),
  rt as (       -- cierres de turno del período
    select r.*, p.nombre_completo from horarios.reportes_turno r
      left join horarios.perfiles p on p.id = r.auxiliar_id
     where r.fecha between p_desde and p_hasta
  )
  select jsonb_build_object(
    -- Horas de uso por día (clases, cedidas, eventos)
    'uso_por_dia', (
      select coalesce(jsonb_agg(x order by x->>'dia'), '[]') from (
        select jsonb_build_object('dia', d::date,
                 'clase',  round(coalesce(sum(o.horas) filter (where o.origen = 'clase'), 0)::numeric, 1),
                 'cesion', round(coalesce(sum(o.horas) filter (where o.origen = 'cesion'), 0)::numeric, 1),
                 'evento', round(coalesce(sum(o.horas) filter (where o.origen = 'reserva'), 0)::numeric, 1)) x
          from generate_series(p_desde, p_hasta, interval '1 day') d
          left join o on o.fecha = d::date
         group by d) s
    ),
    -- Horas de uso por día de la semana (1 = lunes … 7 = domingo)
    'uso_por_dia_semana', (
      select coalesce(jsonb_agg(x order by (x->>'dia')::int), '[]') from (
        select jsonb_build_object('dia', g.n,
                 'clase',  round(coalesce(sum(o.horas) filter (where o.origen = 'clase'), 0)::numeric, 1),
                 'cesion', round(coalesce(sum(o.horas) filter (where o.origen = 'cesion'), 0)::numeric, 1),
                 'evento', round(coalesce(sum(o.horas) filter (where o.origen = 'reserva'), 0)::numeric, 1)) x
          from generate_series(1, 7) g(n)
          left join o on extract(isodow from o.fecha) = g.n
         group by g.n) s
    ),
    -- Horas pico: cuántas horas de laboratorio se usan en cada franja de una hora
    'uso_por_hora', (
      select coalesce(jsonb_agg(x order by (x->>'hora')::int), '[]') from (
        select jsonb_build_object('hora', g.h,
                 'clase',  round(coalesce(sum(ov) filter (where origen = 'clase'), 0)::numeric, 1),
                 'cesion', round(coalesce(sum(ov) filter (where origen = 'cesion'), 0)::numeric, 1),
                 'evento', round(coalesce(sum(ov) filter (where origen = 'reserva'), 0)::numeric, 1)) x
          from generate_series(6, 22) g(h)
          left join lateral (
            select o.origen,
                   greatest(0, extract(epoch from (least(o.hora_fin, make_time(g.h + 1, 0, 0))
                                                   - greatest(o.hora_inicio, make_time(g.h, 0, 0)))) / 3600.0) as ov
              from o
             where o.hora_inicio < make_time(g.h + 1, 0, 0) and o.hora_fin > make_time(g.h, 0, 0)
          ) y on true
         group by g.h) s
    ),
    -- Horas por carrera
    'carreras', (
      select coalesce(jsonb_agg(x order by (x->>'horas')::numeric desc), '[]') from (
        select jsonb_build_object('carrera', coalesce(c.sigla, c.nombre, 'Sin carrera'), 'nombre', coalesce(c.nombre, 'Sin carrera'),
                 'horas', round(sum(o.horas)::numeric, 1), 'sesiones', count(*),
                 'materias', count(distinct o.titulo), 'docentes', count(distinct o.docente_id)) x
          from o left join horarios.carreras c on c.id = o.carrera_id
         where o.origen in ('clase', 'cesion')
         group by c.id, c.sigla, c.nombre
         order by sum(o.horas) desc limit 12) s
    ),
    -- Docentes que más usan los laboratorios
    'docentes', (
      select coalesce(jsonb_agg(x order by (x->>'horas')::numeric desc), '[]') from (
        select jsonb_build_object('docente', trim(d.nombres || ' ' || d.apellidos),
                 'horas', round(sum(o.horas)::numeric, 1), 'sesiones', count(*),
                 'materias', string_agg(distinct o.titulo, ', '),
                 'pedidos', (select count(*) from t where t.docente_id = d.id)) x
          from o join horarios.docentes d on d.id = o.docente_id
         where o.origen in ('clase', 'cesion')
         group by d.id, d.nombres, d.apellidos
         order by sum(o.horas) desc limit 10) s
    ),
    -- Tickets según el turno en que se crearon
    'tickets_por_turno', (
      select coalesce(jsonb_agg(jsonb_build_object('turno', h.turno,
               'tickets', (select count(*) from t where t.turno_creado = h.turno),
               'resueltos', (select count(*) from t where t.turno_creado = h.turno and t.estado = 'resuelto'),
               'horas_resolucion', (select round((avg(extract(epoch from (t.resuelto_en - t.creado_en)) / 3600)
                                     filter (where t.estado = 'resuelto' and t.resuelto_en > t.creado_en + interval '1 minute'))::numeric, 1)
                                      from t where t.turno_creado = h.turno and t.tipo <> 'cambio_estado'))
             order by h.hora_inicio), '[]')
        from horarios.horarios_turno h
    ),
    -- Tickets por día de la semana
    'tickets_por_dia_semana', (
      select coalesce(jsonb_agg(jsonb_build_object('dia', g.n,
               'tickets', (select count(*) from t where extract(isodow from t.local) = g.n),
               'resueltos', (select count(*) from t where extract(isodow from t.local) = g.n and t.estado = 'resuelto'))
             order by g.n), '[]')
        from generate_series(1, 7) g(n)
    ),
    -- Tiempo promedio para resolver por tipo de ticket
    'resolucion_por_tipo', (
      select coalesce(jsonb_agg(x order by (x->>'horas')::numeric desc), '[]') from (
        select jsonb_build_object('tipo', tipo,
                 'horas', round((avg(extract(epoch from (resuelto_en - creado_en)) / 3600))::numeric, 1),
                 'tickets', count(*)) x
          from t
         where tipo <> 'cambio_estado' and estado = 'resuelto' and resuelto_en > creado_en + interval '1 minute'
         group by tipo) s
    ),
    -- Cierres de turno: a tiempo o con retraso
    'cierres', jsonb_build_object(
      'total',      (select count(*) from rt),
      'a_tiempo',   (select count(*) from rt where minutos_retraso = 0),
      'con_retraso',(select count(*) from rt where minutos_retraso > 0),
      'sin_horario',(select count(*) from rt where minutos_retraso is null),
      'retraso_promedio', (select round(avg(minutos_retraso))::int from rt where minutos_retraso > 0),
      'retraso_maximo',   (select max(minutos_retraso) from rt),
      'pcs_baja',   (select coalesce(sum(jsonb_array_length(pcs_baja)), 0) from rt),
      'por_dia', (
        select coalesce(jsonb_agg(jsonb_build_object('dia', d::date,
                 'a_tiempo', (select count(*) from rt where rt.fecha = d::date and rt.minutos_retraso = 0),
                 'con_retraso', (select count(*) from rt where rt.fecha = d::date and rt.minutos_retraso > 0),
                 'sin_horario', (select count(*) from rt where rt.fecha = d::date and rt.minutos_retraso is null)) order by d), '[]')
          from generate_series(p_desde, p_hasta, interval '1 day') d),
      'por_turno', (
        select coalesce(jsonb_agg(jsonb_build_object('turno', h.turno,
                 'cierres', (select count(*) from rt where rt.turno = h.turno),
                 'a_tiempo', (select count(*) from rt where rt.turno = h.turno and rt.minutos_retraso = 0),
                 'sin_horario', (select count(*) from rt where rt.turno = h.turno and rt.minutos_retraso is null),
                 'con_retraso', (select count(*) from rt where rt.turno = h.turno and rt.minutos_retraso > 0),
                 'retraso_promedio', (select round(avg(minutos_retraso))::int from rt where rt.turno = h.turno and rt.minutos_retraso > 0))
               order by h.hora_inicio), '[]')
          from horarios.horarios_turno h),
      'por_auxiliar', (
        select coalesce(jsonb_agg(x order by (x->>'cierres')::int desc), '[]') from (
          select jsonb_build_object('nombre', coalesce(nombre_completo, '—'),
                   'cierres', count(*),
                   'a_tiempo', count(*) filter (where minutos_retraso = 0),
                   'con_retraso', count(*) filter (where minutos_retraso > 0),
                   'retraso_promedio', round(avg(minutos_retraso) filter (where minutos_retraso > 0))::int,
                   'retraso_maximo', max(minutos_retraso),
                   'pcs_baja', coalesce(sum(jsonb_array_length(pcs_baja)), 0)) x
            from rt group by auxiliar_id, nombre_completo) s)
    ),
    -- PCs dadas de baja en el período (siguen de baja) y reactivaciones
    'bajas', (
      select coalesce(jsonb_agg(jsonb_build_object('etiqueta', p.etiqueta, 'lab', am.codigo,
               'motivo', coalesce(p.motivo_baja, p.estado_detalle), 'por', pf.nombre_completo, 'en', p.estado_en)
             order by p.estado_en desc), '[]')
        from horarios.ambiente_pcs p
        left join horarios.ambientes am on am.id = p.ambiente_id
        left join horarios.perfiles pf on pf.id = p.estado_por
       where p.estado = 'baja' and (p.estado_en at time zone v_zona)::date between p_desde and p_hasta
    ),
    'reactivadas', (select count(*) from t where (tipo = 'cambio_estado' and descripcion like '%De baja →%')
                                         or (tipo = 'correctivo' and estado_anterior = 'baja' and estado_final <> 'baja')),
    -- Objetos perdidos
    'objetos', jsonb_build_object(
      'registrados', (select count(*) from horarios.objetos_perdidos where (encontrado_en at time zone v_zona)::date between p_desde and p_hasta),
      'entregados',  (select count(*) from horarios.objetos_perdidos where (entregado_en at time zone v_zona)::date between p_desde and p_hasta),
      'en_custodia', (select count(*) from horarios.objetos_perdidos where estado = 'en_custodia'),
      'por_lab', (
        select coalesce(jsonb_agg(jsonb_build_object('codigo', am.codigo, 'color', am.color, 'objetos', x.n) order by x.n desc), '[]')
          from (select ambiente_id, count(*) n from horarios.objetos_perdidos
                 where (encontrado_en at time zone v_zona)::date between p_desde and p_hasta group by ambiente_id) x
          join horarios.ambientes am on am.id = x.ambiente_id)
    )
  ) into r;
  return r;
end $$;

-- FUNCTION: fn_dashboard_fallas(date, date)
CREATE FUNCTION horarios.fn_dashboard_fallas(p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'horarios'
    AS $$
declare
  v_zona constant text := 'America/La_Paz';
  r jsonb;
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado pueden ver el dashboard.';
  end if;
  if p_desde is null or p_hasta is null or p_hasta < p_desde or (p_hasta - p_desde) > 400 then
    raise exception 'Rango de fechas inválido.';
  end if;

  with c as (   -- correctivos del período
    select a.* from horarios.atenciones a
     where a.tipo = 'correctivo' and (a.creado_en at time zone v_zona)::date between p_desde and p_hasta
  )
  select jsonb_build_object(
    'total', (select count(*) from c),
    'con_ficha', (select count(*) from c where cardinality(fallas) > 0 or falla_otra is not null),
    'fallas', (
      select coalesce(jsonb_agg(x order by (x->>'veces')::int desc), '[]') from (
        select jsonb_build_object('falla', fp.nombre, 'categoria', fp.categoria, 'veces', count(*),
                 'pcs', count(distinct c.pc_id),
                 'labs', (select string_agg(distinct am.codigo, ', ') from horarios.ambientes am where am.id = any (array_agg(c.ambiente_id)))) x
          from c cross join lateral unnest(c.fallas) as u(falla_id)
          join horarios.fallas_pc fp on fp.id = u.falla_id
         group by fp.id, fp.nombre, fp.categoria
         order by count(*) desc limit 15) s
    ),
    'por_categoria', (
      select coalesce(jsonb_agg(jsonb_build_object('categoria', categoria, 'veces', n) order by n desc), '[]')
        from (select fp.categoria, count(*) n
                from c cross join lateral unnest(c.fallas) as u(falla_id)
                join horarios.fallas_pc fp on fp.id = u.falla_id
               group by fp.categoria) s
    ),
    'otras', (
      select coalesce(jsonb_agg(x order by (x->>'veces')::int desc), '[]') from (
        select jsonb_build_object('texto', min(falla_otra), 'veces', count(*), 'ultimo', max(creado_en),
                 'en_lista', exists (select 1 from horarios.fallas_pc fp where lower(trim(fp.nombre)) = lower(trim(min(c.falla_otra))))) x
          from c where falla_otra is not null
         group by lower(trim(falla_otra))
         order by count(*) desc limit 15) s
    ),
    'piezas', (
      select coalesce(jsonb_agg(jsonb_build_object('pieza', pieza, 'veces', n) order by n desc), '[]')
        from (select min(pieza) as pieza, count(*) n from c where pieza is not null group by lower(trim(pieza))) s
    ),
    'reincidentes', (
      select coalesce(jsonb_agg(x order by (x->>'veces')::int desc), '[]') from (
        select jsonb_build_object('etiqueta', pc.etiqueta, 'lab', am.codigo, 'estado', pc.estado, 'veces', count(*),
                 'ultima_falla', (array_agg(c.descripcion order by c.creado_en desc))[1],
                 'ultimo', max(c.creado_en)) x
          from c join horarios.ambiente_pcs pc on pc.id = c.pc_id
          left join horarios.ambientes am on am.id = pc.ambiente_id
         group by pc.id, pc.etiqueta, am.codigo, pc.estado
        having count(*) >= 2
         order by count(*) desc limit 15) s
    ),
    'resultados', jsonb_build_object(
      'activas', (select count(*) from c where estado_final = 'operativa'),
      'mantenimiento', (select count(*) from c where estado_final = 'mantenimiento'),
      'inactivas', (select count(*) from c where estado_final = 'inactiva'),
      'bajas', (select count(*) from c where estado_final = 'baja'),
      'reactivadas', (select count(*) from c where estado_anterior = 'baja' and estado_final <> 'baja'))
  ) into r;
  return r;
end $$;

-- FUNCTION: fn_dashboard_operacion(date, date)
CREATE FUNCTION horarios.fn_dashboard_operacion(p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'horarios'
    AS $$
declare
  v_zona   constant text := 'America/La_Paz';
  v_dias   int := (p_hasta - p_desde) + 1;
  v_ant_desde date := p_desde - ((p_hasta - p_desde) + 1);
  v_ant_hasta date := p_desde - 1;
  r jsonb;
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado pueden ver el dashboard.';
  end if;
  if p_desde is null or p_hasta is null or p_hasta < p_desde or v_dias > 400 then
    raise exception 'Rango de fechas inválido.';
  end if;

  with t as (   -- tickets del período, con su día local
    select a.*, (a.creado_en at time zone v_zona)::date as dia
      from horarios.atenciones a
     where (a.creado_en at time zone v_zona)::date between p_desde and p_hasta
  ),
  personal as (
    select id, nombre_completo, rol, turno_habitual
      from horarios.perfiles
     where rol in ('auxiliar', 'encargado') and activo
  )
  select jsonb_build_object(
    'kpis', (
      select jsonb_build_object(
        'tickets',      count(*),
        'trabajos',     count(distinct coalesce(lote::text, id::text)),
        'resueltos',    count(*) filter (where estado = 'resuelto'),
        'en_proceso',   count(*) filter (where estado = 'en_proceso'),
        'pendientes',   count(*) filter (where estado = 'pendiente'),
        'con_colaboradores', count(distinct coalesce(lote::text, id::text)) filter (where cardinality(colaboradores) > 0),
        'horas_resolucion', round((avg(extract(epoch from (resuelto_en - creado_en)) / 3600)
                              filter (where estado = 'resuelto' and resuelto_en > creado_en + interval '1 minute'))::numeric, 1),
        'tickets_anterior', (select count(*) from horarios.atenciones
                              where (creado_en at time zone v_zona)::date between v_ant_desde and v_ant_hasta),
        'reportes',     (select count(*) from horarios.reportes_turno where fecha between p_desde and p_hasta),
        'tareas_pendientes', (select count(*) from horarios.reporte_tareas where not hecha),
        'pendientes_total',  (select count(*) from horarios.atenciones where estado <> 'resuelto')
      ) from t
    ),
    'por_dia', (
      select coalesce(jsonb_agg(jsonb_build_object('dia', d::date, 'tickets', coalesce(c.n, 0),
                                                   'resueltos', coalesce(c.res, 0)) order by d), '[]')
        from generate_series(p_desde, p_hasta, interval '1 day') d
        left join (select dia, count(*) n, count(*) filter (where estado = 'resuelto') res from t group by dia) c on c.dia = d::date
    ),
    'por_tipo', (
      select coalesce(jsonb_agg(jsonb_build_object('tipo', tipo, 'tickets', n, 'trabajos', w) order by n desc), '[]')
        from (select tipo, count(*) n, count(distinct coalesce(lote::text, id::text)) w from t group by tipo) x
    ),
    'por_lab', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', am.id, 'codigo', am.codigo, 'color', am.color,
               'tickets', (select count(*) from t where t.ambiente_id = am.id),
               'pendientes', (select count(*) from t where t.ambiente_id = am.id and t.estado <> 'resuelto'),
               'pcs', (select jsonb_build_object(
                          'total', count(*),
                          'operativa', count(*) filter (where p.estado = 'operativa'),
                          'inactiva', count(*) filter (where p.estado = 'inactiva'),
                          'mantenimiento', count(*) filter (where p.estado = 'mantenimiento'),
                          'baja', count(*) filter (where p.estado = 'baja'))
                         from horarios.ambiente_pcs p where p.ambiente_id = am.id)
             ) order by am.orden, am.codigo), '[]')
        from horarios.ambientes am
       where am.tipo = 'laboratorio' and am.estado <> 'baja'
    ),
    'auxiliares', (
      select coalesce(jsonb_agg(x order by (x->>'participaciones')::int desc, x->>'nombre'), '[]')
        from (
          select jsonb_build_object(
            'id', p.id, 'nombre', p.nombre_completo, 'rol', p.rol, 'turno', p.turno_habitual,
            -- tickets que registró
            'registrados', (select count(*) from t where t.auxiliar_id = p.id),
            -- trabajos (un lote de 20 PCs = 1 trabajo) que registró
            'trabajos', (select count(distinct coalesce(lote::text, id::text)) from t where t.auxiliar_id = p.id),
            -- tickets donde ayudó sin haberlos registrado
            'colaboraciones', (select count(*) from t where p.id = any(t.colaboradores) and t.auxiliar_id is distinct from p.id),
            'participaciones', (select count(*) from t where t.auxiliar_id = p.id or p.id = any(t.colaboradores)),
            -- resueltos en los que participó (registró o colaboró): al colaborador también le cuentan
            'resueltos', (select count(*) from t where t.estado = 'resuelto' and (t.auxiliar_id = p.id or p.id = any(t.colaboradores))),
            'pcs_atendidas', (select count(distinct pc_id) from t where pc_id is not null and (t.auxiliar_id = p.id or p.id = any(t.colaboradores))),
            'reportes', (select count(*) from horarios.reportes_turno r where r.auxiliar_id = p.id and r.fecha between p_desde and p_hasta),
            'tareas_hechas', (select count(*) from horarios.reporte_tareas rt
                               where rt.hecha_por = p.id and (rt.hecha_en at time zone v_zona)::date between p_desde and p_hasta)
          ) x
          from personal p
        ) s
    ),
    'pcs', (
      select jsonb_build_object(
        'total', count(*),
        'docentes', count(*) filter (where es_docente),
        'operativa', count(*) filter (where estado = 'operativa'),
        'inactiva', count(*) filter (where estado = 'inactiva'),
        'mantenimiento', count(*) filter (where estado = 'mantenimiento'),
        'baja', count(*) filter (where estado = 'baja'))
      from horarios.ambiente_pcs
    ),
    'top_pcs', (
      select coalesce(jsonb_agg(jsonb_build_object('etiqueta', pc.etiqueta, 'lab', am.codigo, 'estado', pc.estado,
                                                   'tickets', x.n, 'ultimo', x.ultimo) order by x.n desc, pc.etiqueta), '[]')
        from (select pc_id, count(*) n, max(creado_en) ultimo from t where pc_id is not null group by pc_id order by count(*) desc limit 10) x
        join horarios.ambiente_pcs pc on pc.id = x.pc_id
        left join horarios.ambientes am on am.id = pc.ambiente_id
    )
  ) into r;
  return r;
end $$;

-- FUNCTION: fn_dashboard_uso(date, date)
CREATE FUNCTION horarios.fn_dashboard_uso(p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'horarios'
    AS $$
declare
  v_zona constant text := 'America/La_Paz';
  r jsonb;
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado pueden ver el uso de laboratorios.';
  end if;
  if p_desde is null or p_hasta is null or p_hasta < p_desde or (p_hasta - p_desde) > 400 then
    raise exception 'Rango de fechas inválido.';
  end if;

  with o as (   -- todo lo que ocupó laboratorios en el período, con sus horas
    select x.*, am.codigo as lab, am.color as lab_color,
           extract(epoch from (x.hora_fin - x.hora_inicio)) / 3600.0 as horas
      from horarios.fn_ocupaciones(p_desde, p_hasta) x
      join horarios.ambientes am on am.id = x.ambiente_id and am.tipo = 'laboratorio'
  ),
  t as (        -- tickets del período, con su día local
    select a.*, (a.creado_en at time zone v_zona)::date as dia
      from horarios.atenciones a
     where (a.creado_en at time zone v_zona)::date between p_desde and p_hasta
  )
  select jsonb_build_object(
    'totales', (
      select jsonb_build_object(
        'horas_clase',  round(coalesce(sum(horas) filter (where origen = 'clase'), 0)::numeric, 1),
        'horas_cesion', round(coalesce(sum(horas) filter (where origen = 'cesion'), 0)::numeric, 1),
        'horas_evento', round(coalesce(sum(horas) filter (where origen = 'reserva'), 0)::numeric, 1),
        'materias',     count(distinct titulo) filter (where origen in ('clase', 'cesion')),
        'eventos',      count(distinct reserva_id) filter (where origen = 'reserva'))
      from o
    ),
    -- Materias: en una cesión cuenta la materia de quien viene
    'materias', (
      select coalesce(jsonb_agg(m order by (m->>'horas')::numeric desc), '[]')
        from (
          select jsonb_build_object(
                   'materia', titulo,
                   'horas', round(sum(horas)::numeric, 1),
                   'sesiones', count(*),
                   'docentes', count(distinct docente_id),
                   'cedidas', count(*) filter (where origen = 'cesion'),
                   'labs', string_agg(distinct lab, ', ')) m
            from o where origen in ('clase', 'cesion')
           group by titulo
           order by sum(horas) desc
           limit 12
        ) s
    ),
    'eventos', (
      select coalesce(jsonb_agg(e order by (e->>'horas')::numeric desc), '[]')
        from (
          select jsonb_build_object(
                   'titulo', titulo,
                   'tipo', estado,
                   'horas', round(sum(horas)::numeric, 1),
                   'dias', count(distinct fecha),
                   'labs', string_agg(distinct lab, ', ')) e
            from o where origen = 'reserva'
           group by titulo, estado
           order by sum(horas) desc
           limit 10
        ) s
    ),
    'por_lab', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'codigo', am.codigo, 'color', am.color,
               'clase',  round(coalesce((select sum(horas) from o where o.ambiente_id = am.id and origen = 'clase'), 0)::numeric, 1),
               'cesion', round(coalesce((select sum(horas) from o where o.ambiente_id = am.id and origen = 'cesion'), 0)::numeric, 1),
               'evento', round(coalesce((select sum(horas) from o where o.ambiente_id = am.id and origen = 'reserva'), 0)::numeric, 1),
               'materia_top', (select titulo from o where o.ambiente_id = am.id and origen in ('clase', 'cesion')
                                group by titulo order by sum(horas) desc limit 1)
             ) order by am.orden, am.codigo), '[]')
        from horarios.ambientes am
       where am.tipo = 'laboratorio' and am.estado <> 'baja'
    ),
    -- Actividad más común de los auxiliares en cada laboratorio
    'actividades_lab', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'codigo', am.codigo, 'color', am.color, 'total', x.total,
               'tipos', x.tipos) order by x.total desc, am.codigo), '[]')
        from (
          select ambiente_id, sum(n) as total,
                 jsonb_agg(jsonb_build_object('tipo', tipo, 'tickets', n) order by n desc) as tipos
            from (select ambiente_id, tipo, count(*) n from t where ambiente_id is not null group by ambiente_id, tipo) y
           group by ambiente_id
        ) x
        join horarios.ambientes am on am.id = x.ambiente_id
    ),
    -- Pedidos más repetidos (mismo texto, sin importar mayúsculas)
    'pedidos', (
      select coalesce(jsonb_agg(p order by (p->>'veces')::int desc), '[]')
        from (
          select jsonb_build_object(
                   'descripcion', min(descripcion),
                   'tipo', tipo,
                   'veces', count(*),
                   'trabajos', count(distinct coalesce(lote::text, id::text)),
                   'pendientes', count(*) filter (where estado <> 'resuelto'),
                   'labs', (select string_agg(distinct am.codigo, ', ') from horarios.ambientes am
                             where am.id = any (array_agg(t.ambiente_id))),
                   'solicitantes', nullif(string_agg(distinct nullif(trim(solicitante), ''), ', '), ''),
                   'ultimo', max(creado_en)) p
            from t
           group by tipo, lower(trim(descripcion))
           order by count(*) desc
           limit 30
        ) s
    )
  ) into r;
  return r;
end $$;

-- FUNCTION: fn_es_admin()
CREATE FUNCTION horarios.fn_es_admin() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select coalesce(horarios.fn_rol_actual() = 'admin', false);
$$;

-- FUNCTION: fn_es_fecha_del_horario(bigint, date)
CREATE FUNCTION horarios.fn_es_fecha_del_horario(p_horario_id bigint, p_fecha date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select exists (
    select 1
    from horarios.asignacion_horarios h
    join horarios.asignaciones a        on a.id = h.asignacion_id
    join horarios.sistemas_academicos s on s.id = a.sistema_id
    where h.id = p_horario_id
      and extract(isodow from p_fecha) = h.dia_semana
      and p_fecha between a.fecha_inicio and a.fecha_fin
      and (s.modo_fechas = 'rango'
           or exists (select 1 from horarios.asignacion_fechas af where af.asignacion_id = a.id and af.fecha = p_fecha))
      and not exists (select 1 from horarios.feriados f where f.fecha = p_fecha)
  );
$$;

-- FUNCTION: fn_estado_ambientes(timestamp without time zone)
CREATE FUNCTION horarios.fn_estado_ambientes(p_momento timestamp without time zone DEFAULT (now() AT TIME ZONE 'America/La_Paz'::text)) RETURNS TABLE(ambiente_id bigint, ocupado boolean, titulo text, detalle text, origen text, hora_inicio time without time zone, hora_fin time without time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select am.id,
         o.clave is not null,
         o.titulo, o.detalle, o.origen, o.hora_inicio, o.hora_fin
  from horarios.ambientes am
  left join lateral (
    select oc.*
    from horarios.fn_ocupaciones(p_momento::date, p_momento::date) oc
    where oc.ambiente_id = am.id
      and oc.hora_inicio <= p_momento::time
      and oc.hora_fin    >  p_momento::time
    order by oc.prioridad desc
    limit 1
  ) o on true
  where am.estado <> 'baja';
$$;

-- FUNCTION: fn_exigir_sin_choques(date, date, text, bigint, date)
CREATE FUNCTION horarios.fn_exigir_sin_choques(p_desde date, p_hasta date, p_tipo text, p_id bigint, p_fecha date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'horarios'
    AS $$
declare
  v_mensaje text;
begin
  if p_desde is null or p_hasta is null then
    return;
  end if;

  select c.mensaje into v_mensaje
  from horarios.fn_conflictos(p_desde, p_hasta) c
  where (p_fecha is null or c.fecha = p_fecha)
    and case p_tipo
          when 'horario'         then p_id in (c.horario_a, c.horario_b)
          when 'asignacion'      then p_id in (c.asignacion_a, c.asignacion_b)
          when 'cesion'          then p_id in (c.cesion_a, c.cesion_b)
          when 'reserva_horario' then p_id in (c.reserva_horario_a, c.reserva_horario_b)
          else false
        end
  limit 1;

  if v_mensaje is not null then
    raise exception '%', v_mensaje
      using errcode = 'P0001',
            hint = 'Elija otro ambiente, cambie el horario, registre una cesión o reubique la clase afectada.';
  end if;
end $$;

-- FUNCTION: fn_generar_pcs(bigint, integer)
CREATE FUNCTION horarios.fn_generar_pcs(p_ambiente_id bigint, p_cantidad integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'horarios'
    AS $$
declare
  v_lab text; v_num text; v_etq text; v_orden int; v_i int := 0; v_creadas int := 0;
begin
  if not horarios.fn_puede_operar() then
    raise exception 'No tiene permisos para generar PCs.';
  end if;
  if p_cantidad is null or p_cantidad < 0 or p_cantidad > 100 then
    raise exception 'Cantidad inválida (0 a 100).';
  end if;
  select codigo into v_lab from horarios.ambientes where id = p_ambiente_id;
  if v_lab is null then raise exception 'Laboratorio no encontrado.'; end if;
  v_num := ltrim(coalesce(nullif(regexp_replace(v_lab, '\D', '', 'g'), ''), p_ambiente_id::text), '0');
  if v_num = '' then v_num := p_ambiente_id::text; end if;

  -- PC docente (orden 0: va primero)
  if not exists (select 1 from horarios.ambiente_pcs where ambiente_id = p_ambiente_id and es_docente) then
    insert into horarios.ambiente_pcs (ambiente_id, etiqueta, estado, orden, es_docente)
    values (p_ambiente_id, 'PCDOCENTE' || v_num, 'operativa', 0, true);
  end if;

  select coalesce(max(orden), 0) into v_orden from horarios.ambiente_pcs where ambiente_id = p_ambiente_id;
  -- Busca el primer número libre y sigue hasta crear p_cantidad máquinas
  while v_creadas < p_cantidad loop
    v_i := v_i + 1;
    if v_i > 999 then exit; end if;
    v_etq := 'SCPC' || v_num || lpad(v_i::text, 2, '0');
    if not exists (select 1 from horarios.ambiente_pcs where ambiente_id = p_ambiente_id and etiqueta = v_etq) then
      v_orden := v_orden + 1;
      insert into horarios.ambiente_pcs (ambiente_id, etiqueta, estado, orden)
      values (p_ambiente_id, v_etq, 'operativa', v_orden);
      v_creadas := v_creadas + 1;
    end if;
  end loop;
  return v_creadas;
end $$;

-- FUNCTION: fn_limpiar_fotos_objetos()
CREATE FUNCTION horarios.fn_limpiar_fotos_objetos() RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'horarios'
    AS $$
begin
  if not horarios.fn_puede_operar() then
    return;
  end if;
  perform set_config('app.limpiando_fotos', 'si', true);
  return query
    with viejos as (
      select id, foto_path, foto_entrega_path from horarios.objetos_perdidos
       where fotos_borradas_en is null and creado_en <= now() - interval '9 months'
       for update
    ), limpiar as (
      update horarios.objetos_perdidos o
         set foto_path = null, foto_entrega_path = null, fotos_borradas_en = now()
        from viejos v where o.id = v.id
    )
    select ruta from viejos v, unnest(array[v.foto_path, v.foto_entrega_path]) as ruta where ruta is not null;
  perform set_config('app.limpiando_fotos', '', true);
end $$;

-- FUNCTION: fn_limpiar_fotos_reporte()
CREATE FUNCTION horarios.fn_limpiar_fotos_reporte() RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'horarios'
    AS $$
begin
  if not horarios.fn_puede_operar() then
    return;
  end if;
  return query
    with vencidas as (
      select id, foto_path from horarios.reportes_turno
       where foto_path is not null and foto_expira <= now()
       for update
    ), limpiar as (
      update horarios.reportes_turno r set foto_path = null
        from vencidas v where r.id = v.id
    )
    select v.foto_path from vencidas v;
end $$;

-- FUNCTION: fn_mediodia_siguiente(timestamp with time zone)
CREATE FUNCTION horarios.fn_mediodia_siguiente(p_momento timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select (((p_momento at time zone 'America/La_Paz')::date
           + case when (p_momento at time zone 'America/La_Paz')::time < time '12:00' then 0 else 1 end)
          + time '12:00') at time zone 'America/La_Paz';
$$;

-- FUNCTION: fn_nombre_docente(bigint)
CREATE FUNCTION horarios.fn_nombre_docente(p_docente_id bigint) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select trim(d.apellidos || ' ' || d.nombres) from horarios.docentes d where d.id = p_docente_id;
$$;

-- FUNCTION: fn_ocupaciones(date, date, bigint, bigint)
CREATE FUNCTION horarios.fn_ocupaciones(p_desde date, p_hasta date, p_ignorar_reserva_id bigint DEFAULT NULL::bigint, p_ignorar_cesion_id bigint DEFAULT NULL::bigint) RETURNS TABLE(clave text, origen text, fecha date, hora_inicio time without time zone, hora_fin time without time zone, ambiente_id bigint, docente_id bigint, asignacion_id bigint, asignacion_horario_id bigint, cesion_id bigint, reserva_id bigint, reserva_horario_id bigint, reubicacion_id bigint, carrera_id bigint, titulo text, detalle text, color text, prioridad integer, estado text)
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  with dias as (
    select g::date as fecha, extract(isodow from g)::smallint as dow
    from generate_series(p_desde, p_hasta, interval '1 day') g
    where not exists (select 1 from horarios.feriados f where f.fecha = g::date)
  ),
  base as (
    select h.id as hid, h.asignacion_id, h.hora_inicio, h.hora_fin, h.ambiente_id,
           a.docente_id, a.materia_id, a.carrera_id, a.grupo, d.fecha
    from horarios.asignacion_horarios h
    join horarios.asignaciones a        on a.id = h.asignacion_id
    join horarios.sistemas_academicos s on s.id = a.sistema_id
    join dias d                       on d.dow = h.dia_semana
                                     and d.fecha between a.fecha_inicio and a.fecha_fin
    where a.fecha_inicio <= p_hasta and a.fecha_fin >= p_desde
      and (s.modo_fechas = 'rango'
           or exists (select 1 from horarios.asignacion_fechas af
                      where af.asignacion_id = a.id and af.fecha = d.fecha))
  ),
  clases as (
    select b.*,
           r.id as rid, r.ambiente_destino_id, r.hora_inicio as rhi, r.hora_fin as rhf,
           cs.id as cid, cs.docente_receptor_id, cs.materia_receptor, cs.carrera_receptor_id, cs.aula_destino
    from base b
    left join horarios.reubicaciones r
           on r.asignacion_horario_id = b.hid and r.fecha = b.fecha
          and (p_ignorar_reserva_id is null or r.reserva_id is distinct from p_ignorar_reserva_id)
          and (p_ignorar_cesion_id  is null or r.cesion_id  is distinct from p_ignorar_cesion_id)
    left join lateral (
      select c.*
      from horarios.cesiones c
      join horarios.cesion_fechas cf on cf.cesion_id = c.id
      where c.asignacion_horario_id = b.hid
        and cf.fecha = b.fecha
        and c.id is distinct from p_ignorar_cesion_id
      order by c.id
      limit 1
    ) cs on true
  )
  select 'C-' || c.hid || '-' || c.fecha,
         'clase',
         c.fecha,
         coalesce(c.rhi, c.hora_inicio),
         coalesce(c.rhf, c.hora_fin),
         case when c.rid is not null then c.ambiente_destino_id else c.ambiente_id end,
         c.docente_id, c.asignacion_id, c.hid, c.cid, null::bigint, null::bigint, c.rid, c.carrera_id,
         m.nombre,
         trim(d.apellidos || ' ' || d.nombres) || ' · ' || ca.nombre || coalesce(' · Gr. ' || c.grupo, ''),
         ca.color,
         10,
         case when c.rid is not null then 'reubicada' else 'normal' end
  from clases c
  join horarios.materias m  on m.id  = c.materia_id
  join horarios.docentes d  on d.id  = c.docente_id
  join horarios.carreras ca on ca.id = c.carrera_id
  where (c.rid is null and c.cid is null)
     or (c.rid is not null and c.ambiente_destino_id is not null and c.cid is null)

  union all

  select 'S-' || c.cid || '-' || c.fecha,
         'cesion',
         c.fecha,
         coalesce(c.rhi, c.hora_inicio),
         coalesce(c.rhf, c.hora_fin),
         case when c.rid is not null then c.ambiente_destino_id else c.ambiente_id end,
         c.docente_receptor_id, c.asignacion_id, c.hid, c.cid, null, null, c.rid,
         coalesce(c.carrera_receptor_id, c.carrera_id),
         coalesce(nullif(c.materia_receptor, ''), cr.nombre, 'Laboratorio cedido'),
         trim(dr.apellidos || ' ' || dr.nombres) || ' · cedido por ' || trim(d.apellidos || ' ' || d.nombres)
           || coalesce(' (se va a ' || nullif(c.aula_destino, '') || ')', ''),
         coalesce(cr.color, '#9333ea'),
         10,
         'cedida'
  from clases c
  join horarios.docentes d  on d.id  = c.docente_id
  join horarios.docentes dr on dr.id = c.docente_receptor_id
  left join horarios.carreras cr on cr.id = c.carrera_receptor_id
  where c.cid is not null
    and (c.rid is null or c.ambiente_destino_id is not null)

  union all

  select 'R-' || rh.id,
         'reserva',
         rh.fecha, rh.hora_inicio, rh.hora_fin, rh.ambiente_id,
         null, null, null, null, r.id, rh.id, null, r.carrera_id,
         r.titulo,
         case r.categoria when 'taller' then 'Taller' when 'conferencia' then 'Conferencia'
                          when 'capacitacion' then 'Capacitación' when 'otros' then 'Evento'
                          else t.nombre end
           || coalesce(' · ' || nullif(r.responsable, ''), ''),
         t.color,
         t.prioridad,
         lower(t.codigo)
  from horarios.reserva_horarios rh
  join horarios.reservas r      on r.id = rh.reserva_id
  join horarios.tipos_reserva t on t.id = r.tipo_id
  where rh.fecha between p_desde and p_hasta
    and r.id is distinct from p_ignorar_reserva_id;
$$;

-- FUNCTION: fn_puede_cerrar_turno(text)
CREATE FUNCTION horarios.fn_puede_cerrar_turno(p_turno text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select case
    when horarios.fn_puede_gestionar_auxiliares() then true
    when horarios.fn_rol_actual() = 'auxiliar' then
      p_turno = horarios.fn_turno_vigente(horarios.fn_usuario_actual())
      and (now() at time zone 'America/La_Paz')::time
          >= coalesce((select h.hora_inicio from horarios.horarios_turno h where h.turno = p_turno), time '00:00')
    else false
  end;
$$;

-- FUNCTION: fn_puede_editar()
CREATE FUNCTION horarios.fn_puede_editar() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select coalesce(horarios.fn_rol_actual() in ('admin', 'decano', 'encargado'), false);
$$;

-- FUNCTION: fn_puede_editar_reporte(bigint)
CREATE FUNCTION horarios.fn_puede_editar_reporte(p_reporte bigint) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select exists (
    select 1 from horarios.reportes_turno r
     where r.id = p_reporte
       and horarios.fn_puede_operar()
       and (horarios.fn_puede_gestionar_auxiliares()
            or (r.auxiliar_id = horarios.fn_usuario_actual()
                and r.fecha = (now() at time zone 'America/La_Paz')::date
                and horarios.fn_puede_cerrar_turno(r.turno))));
$$;

-- FUNCTION: fn_puede_gestionar_auxiliares()
CREATE FUNCTION horarios.fn_puede_gestionar_auxiliares() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select coalesce(horarios.fn_rol_actual() in ('admin','encargado'), false);
$$;

-- FUNCTION: fn_puede_operar()
CREATE FUNCTION horarios.fn_puede_operar() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select coalesce(horarios.fn_rol_actual() in ('admin', 'encargado', 'auxiliar'), false);
$$;

-- FUNCTION: fn_puede_ver()
CREATE FUNCTION horarios.fn_puede_ver() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select coalesce(horarios.fn_rol_actual() <> 'invitado', false);
$$;

-- FUNCTION: fn_rango_asignacion(bigint)
CREATE FUNCTION horarios.fn_rango_asignacion(p_asignacion_id bigint, OUT desde date, OUT hasta date) RETURNS record
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select a.fecha_inicio, a.fecha_fin from horarios.asignaciones a where a.id = p_asignacion_id;
$$;

-- FUNCTION: fn_rol_actual()
CREATE FUNCTION horarios.fn_rol_actual() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'horarios'
    AS $$
  select rol from horarios.perfiles where id = horarios.fn_usuario_actual() and activo;
$$;

-- FUNCTION: fn_set_actualizado_en()
CREATE FUNCTION horarios.fn_set_actualizado_en() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  new.actualizado_en := now();
  return new;
end $$;

-- FUNCTION: fn_texto_fecha(date)
CREATE FUNCTION horarios.fn_texto_fecha(p_fecha date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'horarios'
    AS $$
  -- Ej: "martes 13/10/2026"
  select (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[extract(isodow from p_fecha)::int]
         || ' ' || to_char(p_fecha, 'DD/MM/YYYY');
$$;

-- FUNCTION: fn_texto_hora(time without time zone)
CREATE FUNCTION horarios.fn_texto_hora(p_hora time without time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'horarios'
    AS $$
  select to_char(p_hora, 'HH24:MI');
$$;

-- FUNCTION: fn_trg_atencion_pc_activa()
CREATE FUNCTION horarios.fn_trg_atencion_pc_activa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_estado   text;
  v_etiqueta text;
begin
  if new.pc_id is null or new.tipo = 'cambio_estado'
     or (tg_op = 'UPDATE' and new.pc_id is not distinct from old.pc_id) then
    return new;
  end if;
  select estado, etiqueta into v_estado, v_etiqueta from horarios.ambiente_pcs where id = new.pc_id;
  if new.tipo <> 'correctivo' and v_estado = 'baja' then
    raise exception 'La PC % está de baja: solo se le puede registrar un mantenimiento correctivo (para repararla).', v_etiqueta;
  end if;
  if new.tipo <> 'correctivo' and v_estado is distinct from 'operativa' then
    raise exception 'La PC % está en %: use un mantenimiento correctivo o pásela a Activa primero.', v_etiqueta, v_estado;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_choques_asignacion()
CREATE FUNCTION horarios.fn_trg_choques_asignacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare r record;
begin
  if not exists (select 1 from horarios.asignaciones where id = new.id) then return null; end if;
  select * into r from horarios.fn_rango_asignacion(new.id);
  perform horarios.fn_exigir_sin_choques(r.desde, r.hasta, 'asignacion', new.id);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_asignacion_fecha()
CREATE FUNCTION horarios.fn_trg_choques_asignacion_fecha() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if not exists (select 1 from horarios.asignacion_fechas where asignacion_id = new.asignacion_id and fecha = new.fecha) then
    return null;
  end if;
  perform horarios.fn_exigir_sin_choques(new.fecha, new.fecha, 'asignacion', new.asignacion_id, new.fecha);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_cesion()
CREATE FUNCTION horarios.fn_trg_choques_cesion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_desde date;
  v_hasta date;
begin
  select min(fecha), max(fecha) into v_desde, v_hasta from horarios.cesion_fechas where cesion_id = new.id;
  perform horarios.fn_exigir_sin_choques(v_desde, v_hasta, 'cesion', new.id);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_cesion_fecha()
CREATE FUNCTION horarios.fn_trg_choques_cesion_fecha() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_fila    record := coalesce(new, old);
  v_horario bigint;
begin
  select asignacion_horario_id into v_horario from horarios.cesiones where id = v_fila.cesion_id;
  if v_horario is null then return null; end if;
  perform horarios.fn_exigir_sin_choques(v_fila.fecha, v_fila.fecha, 'horario', v_horario, v_fila.fecha);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_horario()
CREATE FUNCTION horarios.fn_trg_choques_horario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare r record;
begin
  -- El registro pudo borrarse más adelante en la misma transacción
  if not exists (select 1 from horarios.asignacion_horarios where id = new.id) then return null; end if;
  select * into r from horarios.fn_rango_asignacion(new.asignacion_id);
  perform horarios.fn_exigir_sin_choques(r.desde, r.hasta, 'horario', new.id);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_reserva_horario()
CREATE FUNCTION horarios.fn_trg_choques_reserva_horario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if not exists (select 1 from horarios.reserva_horarios where id = new.id) then return null; end if;
  perform horarios.fn_exigir_sin_choques(new.fecha, new.fecha, 'reserva_horario', new.id, new.fecha);
  return null;
end $$;

-- FUNCTION: fn_trg_choques_reubicacion()
CREATE FUNCTION horarios.fn_trg_choques_reubicacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare v_fila record := coalesce(new, old);
begin
  if not exists (select 1 from horarios.asignacion_horarios where id = v_fila.asignacion_horario_id) then
    return null;
  end if;
  perform horarios.fn_exigir_sin_choques(v_fila.fecha, v_fila.fecha, 'horario', v_fila.asignacion_horario_id, v_fila.fecha);
  return null;
end $$;

-- FUNCTION: fn_trg_horario_turno()
CREATE FUNCTION horarios.fn_trg_horario_turno() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  new.actualizado_en := now();
  new.actualizado_por := horarios.fn_usuario_actual();
  return new;
end $$;

-- FUNCTION: fn_trg_objeto_perdido()
CREATE FUNCTION horarios.fn_trg_objeto_perdido() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.estado := 'en_custodia';
    new.encontrado_por := coalesce(new.encontrado_por, horarios.fn_usuario_actual());
    new.entregado_a := null; new.entregado_documento := null; new.entregado_en := null;
    new.entregado_por := null; new.foto_entrega_path := null; new.observacion_entrega := null;
    new.fotos_borradas_en := null;
    return new;
  end if;
  if coalesce(current_setting('app.limpiando_fotos', true), '') = 'si' then
    return new;
  end if;
  new.fotos_borradas_en := old.fotos_borradas_en;
  if old.estado = 'entregado' and not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Este objeto ya fue entregado: solo el administrador o el encargado pueden modificarlo.';
  end if;
  if new.estado = 'entregado' and old.estado = 'en_custodia' then
    new.entregado_en  := now();
    new.entregado_por := horarios.fn_usuario_actual();
  elsif new.estado = 'en_custodia' then
    new.entregado_a := null; new.entregado_documento := null; new.entregado_en := null;
    new.entregado_por := null; new.foto_entrega_path := null; new.observacion_entrega := null;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_pc_baja()
CREATE FUNCTION horarios.fn_trg_pc_baja() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if new.estado = 'baja' then
    if tg_op = 'INSERT' or old.estado is distinct from 'baja' then
      new.motivo_baja := nullif(trim(new.motivo_baja), '');
      if new.motivo_baja is null then
        raise exception 'Indique el motivo para dar de baja %.', new.etiqueta;
      end if;
      new.baja_en  := now();
      new.baja_por := horarios.fn_usuario_actual();
    end if;
  else
    new.motivo_baja := null;
    new.baja_en     := null;
    new.baja_por    := null;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_pc_estado_controlado()
CREATE FUNCTION horarios.fn_trg_pc_estado_controlado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.estado = 'baja' and not horarios.fn_puede_gestionar_auxiliares() then
      raise exception 'Solo el administrador o el encargado pueden registrar una PC de baja.';
    end if;
  elsif new.estado is distinct from old.estado
        and current_setting('app.cambio_estado_pc', true) is distinct from '1' then
    raise exception 'El estado de una PC se cambia desde el croquis o con un mantenimiento correctivo (queda en un ticket).';
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_proteger_admin()
CREATE FUNCTION horarios.fn_trg_proteger_admin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if old.id = horarios.fn_usuario_actual() and (new.rol <> 'admin' or not new.activo) and old.rol = 'admin' then
    raise exception 'No puede quitarse a sí mismo el rol de administrador ni desactivarse.';
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_reporte_foto()
CREATE FUNCTION horarios.fn_trg_reporte_foto() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if new.foto_path is null then
    new.foto_expira := null;
  elsif tg_op = 'INSERT' or new.foto_path is distinct from old.foto_path then
    new.foto_expira := horarios.fn_mediodia_siguiente(now());
  else
    new.foto_expira := old.foto_expira;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_reporte_horario()
CREATE FUNCTION horarios.fn_trg_reporte_horario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare h horarios.horarios_turno;
begin
  if tg_op = 'UPDATE' and new.turno is not distinct from old.turno then
    new.hora_inicio_turno := old.hora_inicio_turno;
    new.hora_fin_turno := old.hora_fin_turno;
    new.minutos_retraso := old.minutos_retraso;
    return new;
  end if;
  select * into h from horarios.horarios_turno where turno = new.turno;
  new.hora_inicio_turno := h.hora_inicio;
  new.hora_fin_turno := h.hora_fin;
  new.minutos_retraso := case when h.hora_fin is null then null else
    greatest(0, floor(extract(epoch from
      (coalesce(new.creado_en, now()) at time zone 'America/La_Paz') - (new.fecha + h.hora_fin)) / 60))::int end;
  return new;
end $$;

-- FUNCTION: fn_trg_reporte_no_borrar_hecho()
CREATE FUNCTION horarios.fn_trg_reporte_no_borrar_hecho() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if exists (select 1 from horarios.reporte_tareas where reporte_id = old.id and hecha) then
    raise exception 'Este reporte ya tiene tareas hechas: no se puede eliminar (sí se puede editar).';
  end if;
  return old;
end $$;

-- FUNCTION: fn_trg_reporte_pcs_baja()
CREATE FUNCTION horarios.fn_trg_reporte_pcs_baja() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare v_desde timestamptz;
begin
  if tg_op = 'UPDATE' then
    new.pcs_baja := old.pcs_baja;
    return new;
  end if;
  -- Desde el inicio del turno (lo pone trg_reportes_turno_horario, que corre antes)
  v_desde := (new.fecha + coalesce(new.hora_inicio_turno, time '00:00')) at time zone 'America/La_Paz';
  select coalesce(jsonb_agg(jsonb_build_object(
           'etiqueta', p.etiqueta, 'lab', am.codigo,
           'motivo', coalesce(p.motivo_baja, p.estado_detalle), 'en', p.estado_en) order by p.estado_en), '[]'::jsonb)
    into new.pcs_baja
    from horarios.ambiente_pcs p
    left join horarios.ambientes am on am.id = p.ambiente_id
   where p.estado = 'baja'
     and p.estado_por = coalesce(new.auxiliar_id, horarios.fn_usuario_actual())
     and p.estado_en >= v_desde
     and p.estado_en <= coalesce(new.creado_en, now());
  return new;
end $$;

-- FUNCTION: fn_trg_reporte_turno_realizado()
CREATE FUNCTION horarios.fn_trg_reporte_turno_realizado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  new.turno_realizado := horarios.fn_turno_de_hora(coalesce(new.creado_en, now()));
  return new;
end $$;

-- FUNCTION: fn_trg_tarea_hecha_fija()
CREATE FUNCTION horarios.fn_trg_tarea_hecha_fija() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.hecha then
      raise exception 'Una tarea hecha no se puede eliminar.';
    end if;
    return old;
  end if;
  if old.hecha then
    if new.descripcion is distinct from old.descripcion or new.ambiente_id is distinct from old.ambiente_id
       or new.reporte_id is distinct from old.reporte_id then
      raise exception 'Una tarea hecha ya no se puede modificar.';
    end if;
    if not new.hecha and not horarios.fn_puede_gestionar_auxiliares() then
      raise exception 'Solo el administrador o el encargado pueden desmarcar una tarea hecha.';
    end if;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_asignacion()
CREATE FUNCTION horarios.fn_trg_validar_asignacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_sistema horarios.sistemas_academicos;
begin
  select * into v_sistema from horarios.sistemas_academicos where id = new.sistema_id;
  if v_sistema.modo_fechas = 'rango' and v_sistema.meses_maximo is not null
     and new.fecha_fin >= (new.fecha_inicio + make_interval(months => v_sistema.meses_maximo))::date then
    raise exception 'En el sistema "%" la duración debe ser menor a % meses (fin máximo: %).',
      v_sistema.nombre, v_sistema.meses_maximo,
      to_char((new.fecha_inicio + make_interval(months => v_sistema.meses_maximo))::date - 1, 'DD/MM/YYYY');
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_asignacion_fecha()
CREATE FUNCTION horarios.fn_trg_validar_asignacion_fecha() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_dias    smallint[];
  v_sistema text;
  v_inicio  date;
  v_fin     date;
begin
  select s.dias_permitidos, s.nombre, a.fecha_inicio, a.fecha_fin into v_dias, v_sistema, v_inicio, v_fin
  from horarios.asignaciones a join horarios.sistemas_academicos s on s.id = a.sistema_id
  where a.id = new.asignacion_id;
  if not (extract(isodow from new.fecha)::smallint = any(v_dias)) then
    raise exception 'El sistema "%" no permite clases el %.', v_sistema, horarios.fn_texto_fecha(new.fecha);
  end if;
  if new.fecha not between v_inicio and v_fin then
    raise exception 'El % está fuera del rango de la asignación.', horarios.fn_texto_fecha(new.fecha);
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_cesion_fecha()
CREATE FUNCTION horarios.fn_trg_validar_cesion_fecha() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_horario  bigint;
  v_receptor bigint;
  v_docente  bigint;
  v_otro     text;
begin
  select c.asignacion_horario_id, c.docente_receptor_id, a.docente_id
    into v_horario, v_receptor, v_docente
  from horarios.cesiones c
  join horarios.asignacion_horarios h on h.id = c.asignacion_horario_id
  join horarios.asignaciones a on a.id = h.asignacion_id
  where c.id = new.cesion_id;

  if v_receptor = v_docente then
    raise exception 'Un docente no puede cederse el ambiente a sí mismo.';
  end if;
  if not horarios.fn_es_fecha_del_horario(v_horario, new.fecha) then
    raise exception 'El % no es un día de clase de ese horario (revise los días marcados de la asignación y los feriados).',
      horarios.fn_texto_fecha(new.fecha);
  end if;
  -- Un mismo día no se puede ceder dos veces
  select horarios.fn_nombre_docente(c.docente_receptor_id) into v_otro
  from horarios.cesiones c join horarios.cesion_fechas cf on cf.cesion_id = c.id
  where c.asignacion_horario_id = v_horario and cf.fecha = new.fecha and c.id <> new.cesion_id
  limit 1;
  if v_otro is not null then
    raise exception 'El % ya fue cedido a %. Edite esa cesión en lugar de crear otra.', horarios.fn_texto_fecha(new.fecha), v_otro;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_horario()
CREATE FUNCTION horarios.fn_trg_validar_horario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_estado  text;
  v_codigo  text;
  v_dias    smallint[];
  v_sistema text;
begin
  select estado, codigo into v_estado, v_codigo from horarios.ambientes where id = new.ambiente_id;
  if v_estado <> 'activo' then
    raise exception 'El ambiente % está en estado "%" y no puede asignarse.', v_codigo, v_estado;
  end if;

  select s.dias_permitidos, s.nombre into v_dias, v_sistema
  from horarios.asignaciones a
  join horarios.sistemas_academicos s on s.id = a.sistema_id
  where a.id = new.asignacion_id;

  if not (new.dia_semana = any(v_dias)) then
    raise exception 'El sistema "%" no permite clases el día %.', v_sistema,
      (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[new.dia_semana];
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_reserva_horario()
CREATE FUNCTION horarios.fn_trg_validar_reserva_horario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_estado text;
  v_codigo text;
begin
  select estado, codigo into v_estado, v_codigo from horarios.ambientes where id = new.ambiente_id;
  if v_estado = 'baja' then
    raise exception 'El ambiente % está dado de baja.', v_codigo;
  end if;
  return new;
end $$;

-- FUNCTION: fn_trg_validar_reubicacion()
CREATE FUNCTION horarios.fn_trg_validar_reubicacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_estado text;
  v_codigo text;
begin
  if not horarios.fn_es_fecha_del_horario(new.asignacion_horario_id, new.fecha) then
    raise exception 'El % no es un día de clase de ese horario.', horarios.fn_texto_fecha(new.fecha);
  end if;
  if new.ambiente_destino_id is not null then
    select estado, codigo into v_estado, v_codigo from horarios.ambientes where id = new.ambiente_destino_id;
    if v_estado <> 'activo' then
      raise exception 'El ambiente % está en estado "%" y no puede usarse.', v_codigo, v_estado;
    end if;
  end if;
  return new;
end $$;

-- FUNCTION: fn_turno_de_hora(timestamp with time zone)
CREATE FUNCTION horarios.fn_turno_de_hora(p_momento timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select case
           when extract(hour from p_momento at time zone 'America/La_Paz') < 11 then 'M'
           when extract(hour from p_momento at time zone 'America/La_Paz') < 14 then 'MD'
           when extract(hour from p_momento at time zone 'America/La_Paz') < 18 then 'T'
           else 'N'
         end;
$$;

-- FUNCTION: fn_turno_vigente(uuid, date)
CREATE FUNCTION horarios.fn_turno_vigente(p_perfil uuid, p_fecha date DEFAULT ((now() AT TIME ZONE 'America/La_Paz'::text))::date) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  select tp.turno from horarios.turnos_programados tp
   where tp.perfil_id = p_perfil and tp.desde <= p_fecha
   order by tp.desde desc limit 1;
$$;

-- FUNCTION: fn_verificar_choques(jsonb, jsonb)
CREATE FUNCTION horarios.fn_verificar_choques(p_items jsonb, p_ignorar jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(indice integer, tipo_choque text, fecha date, hora_inicio time without time zone, hora_fin time without time zone, ambiente_id bigint, docente_id bigint, clave text, origen text, titulo text, detalle text, asignacion_id bigint, asignacion_horario_id bigint, reserva_id bigint, prioridad integer, mensaje text, ocupacion_inicio time without time zone, ocupacion_fin time without time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'horarios'
    AS $$
  with candidatos as (
    -- Cada candidato expandido a fechas concretas
    select (e.ord - 1)::int as idx, f.fecha,
           (e.x->>'hora_inicio')::time as hi, (e.x->>'hora_fin')::time as hf,
           nullif(e.x->>'ambiente_id', '')::bigint as amb,
           nullif(e.x->>'docente_id', '')::bigint  as doc
    from jsonb_array_elements(p_items) with ordinality as e(x, ord)
    cross join lateral (
      select (e.x->>'fecha')::date as fecha
      where nullif(e.x->>'fecha', '') is not null
      union all
      select g::date
      from generate_series((e.x->>'desde')::date, (e.x->>'hasta')::date, interval '1 day') g
      where nullif(e.x->>'fecha', '') is null
        and extract(isodow from g) = (e.x->>'dia_semana')::int
        and not exists (select 1 from horarios.feriados fe where fe.fecha = g::date)
    ) f
  ),
  ignorar as (
    select nullif(p_ignorar->>'asignacion_id', '')::bigint as asig,
           nullif(p_ignorar->>'reserva_id', '')::bigint    as res,
           nullif(p_ignorar->>'cesion_id', '')::bigint     as ces,
           coalesce((select array_agg(x::bigint)
                     from jsonb_array_elements_text(p_ignorar->'asignacion_horario_ids') x), '{}') as hors
  ),
  rango as (
    select min(c.fecha) as desde, max(c.fecha) as hasta from candidatos c
  ),
  o as materialized (
    -- Ocupaciones existentes, sin lo que se está editando
    select oc.*
    from rango, ignorar i,
         lateral horarios.fn_ocupaciones(rango.desde, rango.hasta, i.res, i.ces) oc
    where rango.desde is not null
      and not coalesce(oc.asignacion_id = i.asig, false)
      and not coalesce(oc.asignacion_horario_id = any(i.hors), false)
  )
  select c.idx,
         case when o.ambiente_id = c.amb then 'ambiente' else 'docente' end,
         c.fecha,
         greatest(o.hora_inicio, c.hi), least(o.hora_fin, c.hf),
         o.ambiente_id, o.docente_id, o.clave, o.origen, o.titulo, o.detalle,
         o.asignacion_id, o.asignacion_horario_id, o.reserva_id, o.prioridad,
         case when o.ambiente_id = c.amb then
           format('%s el %s de %s a %s ya está ocupado por "%s" (%s).',
                  am.codigo, horarios.fn_texto_fecha(c.fecha),
                  horarios.fn_texto_hora(o.hora_inicio), horarios.fn_texto_hora(o.hora_fin),
                  o.titulo, o.detalle)
         else
           format('%s ya tiene "%s" en %s el %s de %s a %s.',
                  horarios.fn_nombre_docente(o.docente_id), o.titulo, am.codigo,
                  horarios.fn_texto_fecha(c.fecha),
                  horarios.fn_texto_hora(o.hora_inicio), horarios.fn_texto_hora(o.hora_fin))
         end,
         o.hora_inicio, o.hora_fin
  from candidatos c
  join o on o.fecha = c.fecha and o.hora_inicio < c.hf and c.hi < o.hora_fin
  join horarios.ambientes am on am.id = o.ambiente_id
  where (c.amb is not null and o.ambiente_id = c.amb
         and (c.doc is null or o.docente_id is null or o.docente_id <> c.doc))
     or (c.doc is not null and o.docente_id = c.doc
         and (c.amb is null or o.ambiente_id <> c.amb))
  order by c.fecha, 4;
$$;

-- FUNCTION: rpc_cambiar_estado_pcs(bigint[], text, text, boolean)
CREATE FUNCTION horarios.rpc_cambiar_estado_pcs(p_ids bigint[], p_estado text, p_detalle text, p_ticket boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_detalle text := nullif(trim(p_detalle), '');
  v_lote    uuid;
  v_turno   bigint;
  v_n       integer := 0;
  pc        record;
  v_textos  constant jsonb := '{"operativa":"Activa","inactiva":"Inactiva","mantenimiento":"Mantenimiento","baja":"De baja"}';
begin
  if not horarios.fn_puede_operar() then
    raise exception 'No tiene permiso para cambiar el estado de las PCs.';
  end if;
  if p_estado not in ('operativa', 'inactiva', 'mantenimiento', 'baja') then
    raise exception 'Estado de PC inválido.';
  end if;
  if coalesce(cardinality(p_ids), 0) = 0 then
    raise exception 'Elija al menos una PC.';
  end if;
  if v_detalle is null or char_length(v_detalle) < 3 then
    raise exception '%', case when p_estado = 'baja' then 'Escriba el motivo de la baja (al menos 3 letras).'
                              else 'Escriba qué se reparó o el motivo del cambio (al menos 3 letras).' end;
  end if;
  v_detalle := left(v_detalle, 300);

  select id into v_turno from horarios.turnos_trabajo where estado = 'abierto' order by abierto_en desc limit 1;
  if (select count(*) from horarios.ambiente_pcs where id = any (p_ids) and estado <> p_estado) > 1 then
    v_lote := gen_random_uuid();
  end if;

  perform set_config('app.cambio_estado_pc', '1', true);
  for pc in select * from horarios.ambiente_pcs where id = any (p_ids) and estado <> p_estado order by orden, etiqueta loop
    -- Salir de baja siempre queda registrado como ticket propio
    if p_ticket or pc.estado = 'baja' then
      insert into horarios.atenciones (ambiente_id, pc_id, tipo, alcance, descripcion, solucion, prioridad, estado,
                                     resuelto_por, resuelto_en, lote, turno_trabajo_id)
      values (pc.ambiente_id, pc.id, 'cambio_estado', case when v_lote is null then 'individual' else 'grupal' end,
              format('%s: %s → %s', pc.etiqueta, v_textos->>pc.estado, v_textos->>p_estado),
              v_detalle, 2, 'resuelto', horarios.fn_usuario_actual(), now(), v_lote, v_turno);
    end if;
    update horarios.ambiente_pcs set
      estado         = p_estado,
      motivo_baja    = case when p_estado = 'baja' then v_detalle end,
      estado_por     = horarios.fn_usuario_actual(),
      estado_en      = now(),
      estado_detalle = v_detalle
    where id = pc.id;
    v_n := v_n + 1;
  end loop;
  -- Dar de baja cierra las solicitudes de baja que hubiera pendientes
  if p_estado = 'baja' then
    update horarios.solicitudes_baja set estado = 'aprobada', resuelto_por = horarios.fn_usuario_actual(), resuelto_en = now()
     where pc_id = any (p_ids) and estado = 'pendiente';
  end if;
  perform set_config('app.cambio_estado_pc', '', true);
  return v_n;
end $$;

-- FUNCTION: rpc_guardar_asignacion(jsonb)
CREATE FUNCTION horarios.rpc_guardar_asignacion(p jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_id     bigint := nullif(p->>'id', '')::bigint;
  v_modo   text;
  v_inicio date;
  v_fin    date;
  v_ids    bigint[];
  h        jsonb;
begin
  if jsonb_array_length(coalesce(p->'horarios', '[]')) = 0 then
    raise exception 'Debe registrar al menos un horario (día, hora y laboratorio).';
  end if;

  select modo_fechas into v_modo from horarios.sistemas_academicos where id = (p->>'sistema_id')::bigint;
  if v_modo is null then
    raise exception 'Seleccione el sistema (modular o semestral).';
  end if;

  -- Rango: en modular sale de los días marcados
  if v_modo = 'dias' then
    if jsonb_array_length(coalesce(p->'fechas', '[]')) = 0 then
      raise exception 'Marque en el calendario los días de clase.';
    end if;
    select min((x #>> '{}')::date), max((x #>> '{}')::date) into v_inicio, v_fin
    from jsonb_array_elements(p->'fechas') x;
  else
    v_inicio := nullif(p->>'fecha_inicio', '')::date;
    v_fin    := nullif(p->>'fecha_fin', '')::date;
    if v_inicio is null or v_fin is null then
      raise exception 'Indique la fecha de inicio y de fin.';
    end if;
  end if;

  if v_id is null then
    insert into horarios.asignaciones (sistema_id, docente_id, materia_id, carrera_id, grupo, fecha_inicio, fecha_fin, observacion)
    values ((p->>'sistema_id')::bigint, (p->>'docente_id')::bigint, (p->>'materia_id')::bigint, (p->>'carrera_id')::bigint,
            nullif(p->>'grupo', ''), v_inicio, v_fin, nullif(p->>'observacion', ''))
    returning id into v_id;
  else
    update horarios.asignaciones set
      sistema_id   = (p->>'sistema_id')::bigint,
      docente_id   = (p->>'docente_id')::bigint,
      materia_id   = (p->>'materia_id')::bigint,
      carrera_id   = (p->>'carrera_id')::bigint,
      grupo        = nullif(p->>'grupo', ''),
      fecha_inicio = v_inicio,
      fecha_fin    = v_fin,
      observacion  = nullif(p->>'observacion', '')
    where id = v_id;
    if not found then
      raise exception 'La asignación % no existe.', v_id;
    end if;
  end if;

  -- Días marcados (se reemplazan)
  delete from horarios.asignacion_fechas where asignacion_id = v_id;
  if v_modo = 'dias' then
    insert into horarios.asignacion_fechas (asignacion_id, fecha)
    select distinct v_id, (x #>> '{}')::date from jsonb_array_elements(p->'fechas') x;
  end if;

  -- Se eliminan los horarios que ya no vienen (sus cesiones/reubicaciones caen en cascada)
  select coalesce(array_agg((x->>'id')::bigint), '{}') into v_ids
  from jsonb_array_elements(p->'horarios') x where nullif(x->>'id', '') is not null;

  delete from horarios.asignacion_horarios where asignacion_id = v_id and not (id = any(v_ids));

  for h in select * from jsonb_array_elements(p->'horarios') loop
    if nullif(h->>'id', '') is null then
      insert into horarios.asignacion_horarios (asignacion_id, dia_semana, hora_inicio, hora_fin, ambiente_id)
      values (v_id, (h->>'dia_semana')::smallint, (h->>'hora_inicio')::time, (h->>'hora_fin')::time, (h->>'ambiente_id')::bigint);
    else
      update horarios.asignacion_horarios set
        dia_semana  = (h->>'dia_semana')::smallint,
        hora_inicio = (h->>'hora_inicio')::time,
        hora_fin    = (h->>'hora_fin')::time,
        ambiente_id = (h->>'ambiente_id')::bigint
      where id = (h->>'id')::bigint and asignacion_id = v_id;
    end if;
  end loop;

  return v_id;
end $$;

-- FUNCTION: rpc_guardar_cesion(jsonb)
CREATE FUNCTION horarios.rpc_guardar_cesion(p jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_id      bigint := nullif(p->>'id', '')::bigint;
  v_horario bigint := (p->>'asignacion_horario_id')::bigint;
  v_fecha   date;
begin
  if jsonb_array_length(coalesce(p->'fechas', '[]')) = 0 then
    raise exception 'Seleccione al menos un día para la cesión.';
  end if;
  if nullif(p->>'docente_receptor_id', '') is null then
    raise exception 'Indique qué docente viene al laboratorio.';
  end if;

  if v_id is null then
    insert into horarios.cesiones (asignacion_horario_id, docente_receptor_id, carrera_receptor_id, materia_receptor, motivo, aula_destino)
    values (v_horario, (p->>'docente_receptor_id')::bigint, nullif(p->>'carrera_receptor_id', '')::bigint,
            nullif(trim(p->>'materia_receptor'), ''), coalesce(nullif(trim(p->>'motivo'), ''), 'Cesión de laboratorio'),
            nullif(trim(p->>'aula_destino'), ''))
    returning id into v_id;
  else
    update horarios.cesiones set
      asignacion_horario_id = v_horario,
      docente_receptor_id   = (p->>'docente_receptor_id')::bigint,
      carrera_receptor_id   = nullif(p->>'carrera_receptor_id', '')::bigint,
      materia_receptor      = nullif(trim(p->>'materia_receptor'), ''),
      motivo                = coalesce(nullif(trim(p->>'motivo'), ''), 'Cesión de laboratorio'),
      aula_destino          = nullif(trim(p->>'aula_destino'), '')
    where id = v_id;
    delete from horarios.cesion_fechas where cesion_id = v_id;
  end if;

  for v_fecha in select distinct (x #>> '{}')::date from jsonb_array_elements(p->'fechas') x loop
    insert into horarios.cesion_fechas (cesion_id, fecha) values (v_id, v_fecha);
  end loop;

  return v_id;
end $$;

-- FUNCTION: rpc_guardar_cesiones(jsonb)
CREATE FUNCTION horarios.rpc_guardar_cesiones(p jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_lote  uuid := coalesce(nullif(p->>'lote', '')::uuid, gen_random_uuid());
  v_item  jsonb;
  v_hid   bigint;
  v_id    bigint;
  v_hids  bigint[] := '{}';
begin
  for v_item in select x from jsonb_array_elements(coalesce(p->'horarios', '[]')) x loop
    if jsonb_array_length(coalesce(v_item->'fechas', '[]')) > 0 then
      v_hids := v_hids || (v_item->>'asignacion_horario_id')::bigint;
    end if;
  end loop;
  if cardinality(v_hids) = 0 then
    raise exception 'Seleccione al menos un día para la cesión.';
  end if;

  -- Horarios que estaban en el lote y ya no se ceden
  delete from horarios.cesiones where lote = v_lote and asignacion_horario_id <> all (v_hids);

  for v_item in select x from jsonb_array_elements(p->'horarios') x loop
    if jsonb_array_length(coalesce(v_item->'fechas', '[]')) = 0 then continue; end if;
    v_hid := (v_item->>'asignacion_horario_id')::bigint;
    select id into v_id from horarios.cesiones where lote = v_lote and asignacion_horario_id = v_hid order by id limit 1;
    v_id := horarios.rpc_guardar_cesion(
      (p - 'horarios' - 'lote') || jsonb_build_object('id', v_id, 'asignacion_horario_id', v_hid, 'fechas', v_item->'fechas'));
    update horarios.cesiones set lote = v_lote where id = v_id and lote <> v_lote;
  end loop;

  return v_lote;
end $$;

-- FUNCTION: rpc_guardar_reserva(jsonb)
CREATE FUNCTION horarios.rpc_guardar_reserva(p jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  v_id     bigint := nullif(p->>'id', '')::bigint;
  v_tipo   text   := (select codigo from horarios.tipos_reserva where id = (p->>'tipo_id')::bigint);
  v_titulo text   := nullif(trim(p->>'titulo'), '');
  v_cat    text   := nullif(p->>'categoria', '');
  h jsonb;
begin
  if v_tipo = 'DEFENSA' then
    if nullif(p->>'carrera_id', '') is null then
      raise exception 'Indique la facultad de la defensa.';
    end if;
    v_titulo := coalesce(v_titulo, 'Defensa de grado - ' ||
                (select nombre from horarios.carreras where id = (p->>'carrera_id')::bigint));
    v_cat := null;
  elsif v_tipo = 'EVENTO' and v_cat is null then
    raise exception 'Elija la categoría del evento (taller, conferencia, capacitación u otros).';
  elsif v_tipo <> 'EVENTO' then
    v_cat := null;
  end if;
  if v_titulo is null then
    raise exception 'Indique el nombre del evento.';
  end if;
  if jsonb_array_length(coalesce(p->'horarios', '[]')) = 0 then
    raise exception 'Seleccione al menos una fecha y un ambiente.';
  end if;

  if v_id is null then
    insert into horarios.reservas (tipo_id, titulo, descripcion, responsable, carrera_id, categoria)
    values ((p->>'tipo_id')::bigint, v_titulo, nullif(p->>'descripcion', ''), nullif(p->>'responsable', ''),
            nullif(p->>'carrera_id', '')::bigint, v_cat)
    returning id into v_id;
  else
    update horarios.reservas set
      tipo_id     = (p->>'tipo_id')::bigint,
      titulo      = v_titulo,
      descripcion = nullif(p->>'descripcion', ''),
      responsable = nullif(p->>'responsable', ''),
      carrera_id  = nullif(p->>'carrera_id', '')::bigint,
      categoria   = v_cat
    where id = v_id;
    delete from horarios.reserva_horarios where reserva_id = v_id;
    delete from horarios.reubicaciones    where reserva_id = v_id;
  end if;

  for h in select * from jsonb_array_elements(p->'horarios') loop
    insert into horarios.reserva_horarios (reserva_id, ambiente_id, fecha, hora_inicio, hora_fin)
    values (v_id, (h->>'ambiente_id')::bigint, (h->>'fecha')::date, (h->>'hora_inicio')::time, (h->>'hora_fin')::time);
  end loop;

  for h in select * from jsonb_array_elements(coalesce(p->'reubicaciones', '[]')) loop
    begin
      insert into horarios.reubicaciones (asignacion_horario_id, fecha, ambiente_destino_id, aula_destino, hora_inicio, hora_fin, motivo, reserva_id)
      values ((h->>'asignacion_horario_id')::bigint, (h->>'fecha')::date, nullif(h->>'ambiente_destino_id', '')::bigint,
              nullif(trim(h->>'aula_destino'), ''), nullif(h->>'hora_inicio', '')::time, nullif(h->>'hora_fin', '')::time,
              'Reubicada por: ' || v_titulo, v_id);
    exception when unique_violation then
      raise exception 'Una clase afectada del % ya tiene otra reubicación. Revísela antes de crear la reserva.',
        horarios.fn_texto_fecha((h->>'fecha')::date);
    end;
  end loop;

  return v_id;
end $$;

-- FUNCTION: rpc_registrar_reparaciones(jsonb, uuid[], integer)
CREATE FUNCTION horarios.rpc_registrar_reparaciones(p_fichas jsonb, p_colaboradores uuid[] DEFAULT '{}'::uuid[], p_prioridad integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  f        jsonb;
  pc       record;
  v_lote   uuid;
  v_turno  bigint;
  v_n      int := 0;
  v_fallas bigint[];
  v_nombres text;
  v_otra   text;
  v_diag   text;
  v_corr   text;
  v_pieza  text;
  v_final  text;
  v_bajas  bigint[] := '{}';
begin
  if not horarios.fn_puede_operar() then
    raise exception 'No tiene permiso para registrar reparaciones.';
  end if;
  if jsonb_typeof(p_fichas) is distinct from 'array' or jsonb_array_length(p_fichas) = 0 then
    raise exception 'Elija al menos una PC.';
  end if;
  if jsonb_array_length(p_fichas) > 60 then
    raise exception 'Son demasiadas PCs a la vez (máximo 60).';
  end if;
  if jsonb_array_length(p_fichas) > 1 then
    v_lote := gen_random_uuid();
  end if;
  select id into v_turno from horarios.turnos_trabajo where estado = 'abierto' order by abierto_en desc limit 1;

  perform set_config('app.cambio_estado_pc', '1', true);
  for f in select * from jsonb_array_elements(p_fichas) loop
    select * into pc from horarios.ambiente_pcs where id = (f->>'pc_id')::bigint;
    if not found then
      raise exception 'Una de las PCs ya no existe: recargue la página.';
    end if;

    v_fallas := coalesce(array(select distinct x::bigint from jsonb_array_elements_text(coalesce(f->'fallas', '[]'::jsonb)) x), '{}');
    if exists (select 1 from unnest(v_fallas) i where not exists (select 1 from horarios.fallas_pc fp where fp.id = i)) then
      raise exception '%: una de las fallas elegidas ya no existe.', pc.etiqueta;
    end if;
    v_otra  := left(nullif(trim(f->>'falla_otra'), ''), 120);
    v_diag  := left(nullif(trim(f->>'diagnostico'), ''), 300);
    v_corr  := left(nullif(trim(f->>'correccion'), ''), 1000);
    v_pieza := left(nullif(trim(f->>'pieza'), ''), 60);
    v_final := f->>'estado_final';

    if cardinality(v_fallas) = 0 and v_otra is null then
      raise exception '%: elija al menos una falla o escriba la falla en "Otra".', pc.etiqueta;
    end if;
    if v_otra is not null and char_length(v_otra) < 3 then
      raise exception '%: describa la otra falla con al menos 3 letras.', pc.etiqueta;
    end if;
    if v_final is null or v_final not in ('operativa', 'inactiva', 'mantenimiento', 'baja') then
      raise exception '%: elija cómo queda la PC (estado final).', pc.etiqueta;
    end if;
    if v_final = 'operativa' and coalesce(char_length(v_corr), 0) < 3 then
      raise exception '%: escriba qué se corrigió para dejarla Activa.', pc.etiqueta;
    end if;
    if v_final = 'baja' and coalesce(char_length(v_corr), 0) < 3 then
      raise exception '%: escriba el motivo de la baja.', pc.etiqueta;
    end if;

    select string_agg(fp.nombre, ', ' order by fp.orden, fp.nombre) into v_nombres
      from horarios.fallas_pc fp where fp.id = any (v_fallas);
    v_nombres := concat_ws(', ', v_nombres, v_otra);
    if char_length(v_nombres) < 3 then
      v_nombres := 'Falla: ' || v_nombres;
    end if;

    insert into horarios.atenciones (ambiente_id, pc_id, tipo, alcance, descripcion, solucion, detalles, prioridad, estado,
                                   resuelto_por, resuelto_en, lote, turno_trabajo_id, colaboradores,
                                   fallas, falla_otra, pieza, estado_anterior, estado_final)
    values (pc.ambiente_id, pc.id, 'correctivo', case when v_lote is null then 'individual' else 'grupal' end,
            left(v_nombres, 500), v_corr,
            jsonb_strip_nulls(jsonb_build_object('diagnostico', v_diag, 'pieza', v_pieza,
              'resultado', case v_final when 'operativa' then 'reparada' when 'mantenimiento' then 'sigue'
                                        when 'baja' then 'requiere_baja' else 'inactiva' end)),
            least(3, greatest(1, coalesce(p_prioridad, 2))),
            -- Si queda en mantenimiento, el trabajo sigue abierto (pase de turno)
            case when v_final = 'mantenimiento' then 'en_proceso' else 'resuelto' end,
            case when v_final = 'mantenimiento' then null else horarios.fn_usuario_actual() end,
            case when v_final = 'mantenimiento' then null else now() end,
            v_lote, v_turno, coalesce(p_colaboradores, '{}'), v_fallas, v_otra, v_pieza, pc.estado, v_final);

    if pc.estado is distinct from v_final then
      update horarios.ambiente_pcs set
        estado         = v_final,
        motivo_baja    = case when v_final = 'baja' then left(v_nombres || ': ' || v_corr, 300) end,
        estado_por     = horarios.fn_usuario_actual(),
        estado_en      = now(),
        estado_detalle = left(coalesce(v_corr, v_diag, v_nombres), 300)
      where id = pc.id;
    end if;
    if v_final = 'baja' then
      v_bajas := v_bajas || pc.id;
    end if;
    v_n := v_n + 1;
  end loop;

  -- Dar de baja cierra las solicitudes de baja que hubiera pendientes
  if cardinality(v_bajas) > 0 then
    update horarios.solicitudes_baja set estado = 'aprobada', resuelto_por = horarios.fn_usuario_actual(), resuelto_en = now()
     where pc_id = any (v_bajas) and estado = 'pendiente';
  end if;
  perform set_config('app.cambio_estado_pc', '', true);
  return v_n;
end $$;

-- FUNCTION: rpc_resolver_baja(bigint, boolean, text)
CREATE FUNCTION horarios.rpc_resolver_baja(p_id bigint, p_aprobar boolean, p_respuesta text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare
  s record;
begin
  if not horarios.fn_puede_gestionar_auxiliares() then
    raise exception 'Solo el administrador o el encargado resuelven las solicitudes de baja.';
  end if;
  select * into s from horarios.solicitudes_baja where id = p_id and estado = 'pendiente' for update;
  if not found then
    raise exception 'La solicitud ya fue resuelta.';
  end if;
  if p_aprobar then
    perform horarios.rpc_cambiar_estado_pcs(array[s.pc_id], 'baja',
      coalesce(nullif(trim(p_respuesta), ''), s.motivo));
  else
    if nullif(trim(p_respuesta), '') is null then
      raise exception 'Escriba por qué se rechaza la baja.';
    end if;
  end if;
  update horarios.solicitudes_baja set
    estado = case when p_aprobar then 'aprobada' else 'rechazada' end,
    resuelto_por = horarios.fn_usuario_actual(), resuelto_en = now(),
    respuesta = nullif(trim(p_respuesta), '')
  where id = p_id;
end $$;

-- FUNCTION: rpc_reubicar_clase(jsonb)
CREATE FUNCTION horarios.rpc_reubicar_clase(p jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'horarios'
    AS $$
declare v_id bigint;
begin
  if nullif(trim(p->>'motivo'), '') is null then
    raise exception 'Indique el motivo de la reubicación.';
  end if;

  insert into horarios.reubicaciones (asignacion_horario_id, fecha, ambiente_destino_id, hora_inicio, hora_fin, motivo)
  values ((p->>'asignacion_horario_id')::bigint, (p->>'fecha')::date, nullif(p->>'ambiente_destino_id', '')::bigint,
          nullif(p->>'hora_inicio', '')::time, nullif(p->>'hora_fin', '')::time, p->>'motivo')
  on conflict (asignacion_horario_id, fecha) do update set
    ambiente_destino_id = excluded.ambiente_destino_id,
    hora_inicio         = excluded.hora_inicio,
    hora_fin            = excluded.hora_fin,
    motivo              = excluded.motivo
  returning id into v_id;
  return v_id;
end $$;

-- TABLE: ambiente_pcs
CREATE TABLE horarios.ambiente_pcs (
    id bigint NOT NULL,
    ambiente_id bigint NOT NULL,
    etiqueta text NOT NULL,
    procesador text,
    ram text,
    almacenamiento text,
    estado text DEFAULT 'operativa'::text NOT NULL,
    notas text,
    orden integer DEFAULT 0 NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    es_docente boolean DEFAULT false NOT NULL,
    motivo_baja text,
    baja_en timestamp with time zone,
    baja_por uuid,
    estado_por uuid,
    estado_en timestamp with time zone,
    estado_detalle text,
    CONSTRAINT ambiente_pcs_estado_check CHECK ((estado = ANY (ARRAY['operativa'::text, 'inactiva'::text, 'mantenimiento'::text, 'baja'::text]))),
    CONSTRAINT ambiente_pcs_motivo_baja_largo CHECK ((char_length(motivo_baja) <= 300)),
    CONSTRAINT ambiente_pcs_textos_check CHECK ((((char_length(btrim(etiqueta)) >= 1) AND (char_length(btrim(etiqueta)) <= 30)) AND ((procesador IS NULL) OR (char_length(procesador) <= 60)) AND ((ram IS NULL) OR (char_length(ram) <= 60)) AND ((almacenamiento IS NULL) OR (char_length(almacenamiento) <= 60)) AND ((notas IS NULL) OR (char_length(notas) <= 500))))
);

