-- TABLE: atenciones
CREATE TABLE horarios.atenciones (
    id bigint NOT NULL,
    turno_trabajo_id bigint,
    ambiente_id bigint,
    pc_id bigint,
    docente_id bigint,
    solicitante text,
    tipo text DEFAULT 'docente'::text NOT NULL,
    descripcion text NOT NULL,
    prioridad smallint DEFAULT 2 NOT NULL,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    auxiliar_id uuid DEFAULT horarios.fn_usuario_actual(),
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    resuelto_por uuid,
    resuelto_en timestamp with time zone,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    alcance text DEFAULT 'individual'::text NOT NULL,
    solucion text,
    lote uuid,
    colaboradores uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    detalles jsonb DEFAULT '{}'::jsonb NOT NULL,
    fallas bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    falla_otra text,
    pieza text,
    estado_anterior text,
    estado_final text,
    CONSTRAINT atenciones_alcance_check CHECK ((alcance = ANY (ARRAY['individual'::text, 'grupal'::text]))),
    CONSTRAINT atenciones_detalles_check CHECK (((jsonb_typeof(detalles) = 'object'::text) AND (pg_column_size(detalles) <= 4000))),
    CONSTRAINT atenciones_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'en_proceso'::text, 'resuelto'::text]))),
    CONSTRAINT atenciones_ficha_check CHECK ((((falla_otra IS NULL) OR (char_length(falla_otra) <= 120)) AND ((pieza IS NULL) OR (char_length(pieza) <= 60)) AND ((estado_anterior IS NULL) OR (estado_anterior = ANY (ARRAY['operativa'::text, 'inactiva'::text, 'mantenimiento'::text, 'baja'::text]))) AND ((estado_final IS NULL) OR (estado_final = ANY (ARRAY['operativa'::text, 'inactiva'::text, 'mantenimiento'::text, 'baja'::text]))))),
    CONSTRAINT atenciones_prioridad_check CHECK (((prioridad >= 1) AND (prioridad <= 3))),
    CONSTRAINT atenciones_textos_check CHECK ((((char_length(btrim(descripcion)) >= 3) AND (char_length(btrim(descripcion)) <= 500)) AND ((solucion IS NULL) OR (char_length(solucion) <= 1000)) AND ((solicitante IS NULL) OR (char_length(solicitante) <= 120)))),
    CONSTRAINT atenciones_tipo_check CHECK ((tipo = ANY (ARRAY['docente'::text, 'programas'::text, 'preventivo'::text, 'correctivo'::text, 'personal'::text, 'cambio_estado'::text])))
);

