    CONSTRAINT objetos_perdidos_entrega_completa CHECK (((estado = 'en_custodia'::text) OR ((NULLIF(TRIM(BOTH FROM entregado_a), ''::text) IS NOT NULL) AND (entregado_en IS NOT NULL) AND ((foto_entrega_path IS NOT NULL) OR (fotos_borradas_en IS NOT NULL))))),
    CONSTRAINT objetos_perdidos_entregado_a_check CHECK (((entregado_a IS NULL) OR (char_length(entregado_a) <= 120))),
    CONSTRAINT objetos_perdidos_entregado_documento_check CHECK (((entregado_documento IS NULL) OR (char_length(entregado_documento) <= 30))),
    CONSTRAINT objetos_perdidos_estado_check CHECK ((estado = ANY (ARRAY['en_custodia'::text, 'entregado'::text]))),
    CONSTRAINT objetos_perdidos_foto_check CHECK (((foto_path IS NOT NULL) OR (fotos_borradas_en IS NOT NULL))),
    CONSTRAINT objetos_perdidos_nombre_check CHECK (((char_length(TRIM(BOTH FROM nombre)) >= 2) AND (char_length(TRIM(BOTH FROM nombre)) <= 120))),
    CONSTRAINT objetos_perdidos_observacion_entrega_check CHECK (((observacion_entrega IS NULL) OR (char_length(observacion_entrega) <= 300)))
